const wfList = $('n8n API — Listar Workflows').item.json;
const errList = $('n8n API — Execuções com Erro').item.json;

const workflows = wfList.data || [];
const errors    = errList.data || [];

const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const total    = workflows.length;
const active   = workflows.filter(w => w.active).length;
const inactive = total - active;

// Salva resumo no static data para comparacao futura
const staticData = $getWorkflowStaticData('global');
const prevSnap   = staticData['wf_snapshot'] || {};

const changes = [];
for (const wf of workflows) {
  const prev = prevSnap[wf.id];
  if (prev && prev.active !== wf.active) {
    changes.push(wf.name + ' ficou ' + (wf.active ? 'ATIVO' : 'INATIVO'));
  }
}

const newSnap = {};
for (const wf of workflows) { newSnap[wf.id] = { name: wf.name, active: wf.active }; }
staticData['wf_snapshot'] = newSnap;
staticData['wf_last_backup'] = now;

// Erros recentes (agrupados por workflow)
const errByWf = {};
for (const e of errors) {
  const wfName = e.workflowData?.name || e.workflowId || 'Desconhecido';
  errByWf[wfName] = (errByWf[wfName] || 0) + 1;
}
const errFacts = Object.entries(errByWf).map(([n, c]) => ({ name: n, value: String(c) + ' erro(s)' }));

const wfFacts = workflows.map(w => ({
  name: w.name,
  value: w.active ? 'Ativo' : 'Inativo'
}));

const sections = [
  {
    activityTitle: 'Backup Semanal de Workflows — ' + now,
    activitySubtitle: total + ' workflows | ' + active + ' ativos | ' + inactive + ' inativos',
    facts: [
      { name: 'Total',            value: String(total) },
      { name: 'Ativos',           value: String(active) },
      { name: 'Inativos',         value: String(inactive) },
      { name: 'Alteracoes (7d)',  value: changes.length > 0 ? changes.join('; ') : 'Nenhuma' },
      { name: 'Erros recentes',   value: errors.length > 0 ? String(errors.length) + ' execucoes com falha' : 'Nenhum' }
    ],
    markdown: true
  },
  {
    activityTitle: 'Status de Cada Workflow',
    facts: wfFacts,
    markdown: true
  }
];

if (errFacts.length > 0) {
  sections.push({
    activityTitle: 'Workflows com Falhas Recentes',
    facts: errFacts,
    markdown: true
  });
}

return [{ json: {
  teams_body: JSON.stringify({
    '@type': 'MessageCard',
    '@context': 'http://schema.org/extensions',
    themeColor: inactive > 0 ? 'FFA500' : '00B050',
    summary: 'Backup n8n: ' + total + ' workflows (' + active + ' ativos)',
    sections
  })
} }];
